SELECT

FROM t_ai_token
LEFT JOIN t_ai_channel_group cg ON cg.channel_group_id = t_ai_token.channel_group_id AND cg.deleted_flag = 0

    t_ai_token.deleted_flag = 0

        AND t_ai_token.employee_id = #{queryForm.employeeId}


        AND t_ai_token.channel_group_id = #{queryForm.channelGroupId}


        AND INSTR(t_ai_token.token_name, #{queryForm.tokenName})


        AND t_ai_token.disabled_flag = #{queryForm.disabledFlag}


ORDER BY t_ai_token.create_time DESC
